void Solver::bump_var(int var, double coeff) {
    // Lazy global rescaling: only when the increment factor itself would overflow
    static const double LIMIT = 1e100;
    static const double SCALE = 1e-100;
    if (var_inc > LIMIT) {
        // Scale all activities in a tight loop
        double *p = &activity[1];
        for (int i = vars; i > 0; --i) {
            *p++ *= SCALE;
        }
        var_inc *= SCALE;
    }
    // Update activity of the target variable
    activity[var] += var_inc * coeff;
    // Keep the VSIDS priority queue consistent
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
